const raw = $input.first().json;
const body = raw.body || raw;
const question = String(body.question || body.query || body.q || '').trim();

if (!question) {
  throw new Error('No question provided. POST a JSON body like { "question": "What is our warranty policy?" }');
}

// Postgres full-text search over rag_documents.search_vector.
// websearch_to_tsquery ANDs every term, which returns nothing for a natural
// sentence, so build an OR-joined to_tsquery instead and let ranking decide.
const STOP = new Set(['what','which','who','whom','whose','when','where','why','how','is','are','was','were','be','been','being','do','does','did','the','a','an','and','or','of','to','in','on','for','with','about','our','my','your','their','we','i','you','they','it','this','that','these','those','can','could','should','would','will','shall','may','might','must','have','has','had','if','at','by','from','as','me','tell','explain','please']);

const terms = question
  .toLowerCase()
  .replace(/[^a-z0-9\s]/g, ' ')
  .split(/\s+/)
  .filter(t => t.length > 2 && !STOP.has(t));

const unique = [...new Set(terms)];
// Fall back to the raw words if stopword removal stripped everything.
const finalTerms = unique.length ? unique : question.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(Boolean);

if (!finalTerms.length) {
  throw new Error('Could not derive any searchable terms from the question: ' + question);
}

return [{ json: { question, tsquery: finalTerms.join(' | ') } }];

const question = $('Extract Question').first().json.question;

// PostgREST returns an array of rows; n8n splits it into one item per row.
const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.content);

let context = '';
const sources = [];

rows.forEach((doc, i) => {
  const title = doc.doc_title || 'Document';
  const section = doc.section ? ` / ${doc.section}` : '';
  context += `[Source ${i + 1}] ${title}${section}:\n${doc.content}\n\n`;
  sources.push({
    title: title,
    section: doc.section || null,
    source_file: doc.source_file || null,
    page_number: doc.page_number ?? null
  });
});

if (!rows.length) {
  context = 'No relevant documents were found in the NEXUS OS knowledge base for this question.';
}

return [{ json: {
  question,
  context: context.substring(0, 8000),
  sources,
  doc_count: sources.length
} }];

const aiResponse = $input.first().json;
const context = $('Build RAG Context').first().json;

let answer = 'Sorry, I could not generate an answer.';
if (aiResponse.error) {
  answer = 'The AI model call failed: ' + JSON.stringify(aiResponse.error).substring(0, 300);
} else if (aiResponse.choices && aiResponse.choices[0] && aiResponse.choices[0].message) {
  answer = aiResponse.choices[0].message.content;
}

return [{ json: {
  question: context.question,
  answer: answer,
  sources: context.sources,
  documents_consulted: context.doc_count,
  model: 'google/gemini-2.5-flash',
  timestamp: new Date().toISOString()
} }];
